/*global chrome*/
import React, {useEffect, useState} from 'react';
import FormControl from '@mui/material/FormControl';
import FormGroup from '@mui/material/FormGroup';
import FormControlLabel from '@mui/material/FormControlLabel';
import Switch from '@mui/material/Switch';
import classes from './ControlButtons.module.css'

import { alpha, styled } from '@mui/material/styles';
import { pink } from '@mui/material/colors';

const ControlSwitch = styled(Switch)(({ theme }) => ({
  width: '70px',
  height: '48px',
  '& .MuiButtonBase-root': {
    top: '10%',
    left: '5px',
  },
  '& .MuiSwitch-switchBase': {
    color: '#CECECF',
    transform: 'translateX(2px)',
  },
  '& .MuiSwitch-switchBase.Mui-checked': {
    color: '#0281FF',
    '&:hover': {
      backgroundColor: alpha(pink[600], theme.palette.action.hoverOpacity),
    },
  },
  '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
    backgroundColor: '#EDEDED',
    opacity: 1
  },
  '& .MuiSwitch-track': {
    backgroundColor: '#EDEDED',
    borderRadius: '12px',
    opacity: 1
  },
}));


const ControlButtonsFeed = () => {
  const [onlyAds, setOnlyAds] = useState(false);
  const [autoScroll, setAutoScroll] = useState(false);

  const handleChangeOnlyAds = () => {
    setOnlyAds(value => !value);
  };

  const handleChangeAutoScroll = () => {
    setAutoScroll(value => !value);
  };

  useEffect(() => {
    chrome.storage.local.get(['onlyAds', 'autoScroll'], function(item) {
      setOnlyAds(item?.onlyAds);
      setAutoScroll(item?.autoScroll);
    });
  }, []);

  useEffect(() => {
    if (!onlyAds) {
      chrome.storage.local.set({'onlyAds': false}, function() {});

      return;
    }

    chrome.storage.local.set({'onlyAds': true}, function() {});
  }, [onlyAds]);

  useEffect(() => {
    if (!autoScroll) {
      chrome.storage.local.set({'autoScroll': false}, function() {});

      return;
    }

    chrome.storage.local.set({'autoScroll': true}, function() {});
  }, [autoScroll]);

  return (
    <FormControl component="fieldset" variant="standard" className={classes.controlMain}>
      <FormGroup>
        <FormControlLabel
          className={classes.controlLabelWrapper}
          control={
            <ControlSwitch checked={onlyAds} onChange={handleChangeOnlyAds} name="ads" />
          }
          label={<span className={classes.label}>{'Show Only Ads'}</span>}
        />
        <FormControlLabel
          className={classes.controlLabelWrapper}
          control={
            <ControlSwitch checked={autoScroll} onChange={handleChangeAutoScroll} name="scroll" />
          }
          label={<span className={classes.label}>{'Auto Scroll'}</span>}
        />
      </FormGroup>
    </FormControl>
  );
};

export default ControlButtonsFeed;