/*global chrome*/
import React, {useEffect, useState} from 'react';
import {alpha, styled} from "@mui/material/styles";
import Switch from "@mui/material/Switch";
import {pink} from "@mui/material/colors";
import classes from './ControlButtons.module.css'
import FormControl from "@mui/material/FormControl";
import FormGroup from "@mui/material/FormGroup";
import FormControlLabel from "@mui/material/FormControlLabel";

const ControlSwitch = styled(Switch)(({ theme }) => ({
  width: '70px',
  height: '48px',
  '& .MuiButtonBase-root': {
    top: '10%',
    left: '5px',
  },
  '& .MuiSwitch-switchBase': {
    color: '#CECECF',
    transform: 'translateX(2px)',
  },
  '& .MuiSwitch-switchBase.Mui-checked': {
    color: '#0281FF',
    '&:hover': {
      backgroundColor: alpha(pink[600], theme.palette.action.hoverOpacity),
    },
  },
  '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
    backgroundColor: '#EDEDED',
    opacity: 1
  },
  '& .MuiSwitch-track': {
    backgroundColor: '#EDEDED',
    borderRadius: '12px',
    opacity: 1
  },
}));


const ControlButtonsLibrary = () => {
  const [hideSpendAndSave, setHideSpendAndSave] = useState(null);

  const toggleHideSpendAndSave = () => {
    setHideSpendAndSave((v) => !v);
  };

  useEffect(() => {
    chrome.storage.local.get(['hideSpendAndSave'], function(item) {
      setHideSpendAndSave(item?.hideSpendAndSave);
    });
  }, []);

  useEffect(() => {
    if (null === hideSpendAndSave) {
      return;
    }

    if (!hideSpendAndSave) {
      chrome.storage.local.set({'hideSpendAndSave': false}, function() {});

      return;
    }

    chrome.storage.local.set({'hideSpendAndSave': true}, function() {});
  }, [hideSpendAndSave]);

  return (
    <FormControl component="fieldset" variant="standard" className={classes.controlMain}>
      <FormGroup>
        {hideSpendAndSave !== null && <FormControlLabel
          className={classes.controlLabelWrapper}
          control={
            <ControlSwitch checked={hideSpendAndSave} onChange={toggleHideSpendAndSave} name="hideSpendAndSave" />
          }
          label={<span className={classes.label}>{'Hide spend/Save to storage'}</span>}
        />}
      </FormGroup>
    </FormControl>
  );
};

export default ControlButtonsLibrary;