import React from 'react';
import arrow from '../../arrow.png';
import newLogo from '../../newLogo.svg';
import './App.css';
import RedirectButtons from "./components/RedirectButtons/RedirectButtons";
import ControlButtonsFeed from "./components/ControlButtons/ControlButtonsFeed";
import classes from "./components/ControlButtons/ControlButtons.module.css";
import classesButtonRedirect from "./components/RedirectButtons/RedirectButtons.module.css";
import Button from "@mui/material/Button";
import ControlButtonsLibrary from "./components/ControlButtons/ControlButtonsLibrary";

function App() {
  const handleOpenNewTab = (urlCustom: string | URL | undefined) => {
    window.open(urlCustom, '_blank')
  };

  return (
    <div className="App">
      <header className="App-header">
        <div className={'titleWrapper'}>
          {/*<img src={logo} alt="logo" />*/}
          {/*<span className={'title'}>{"Ad Library Cloud"}</span>*/}
          <img src={newLogo} alt="logo" className={'logo'}/>
        </div>
        {/*<RedirectButtons/>*/}
        <div className={classes.actionButtonWrapper}>
          <Button className={classesButtonRedirect.actionButton} onClick={() => handleOpenNewTab('https://www.facebook.com/ads/library/?country=ALL')} variant="contained">{'Go to Facebook Ads Library'}</Button>
          <ControlButtonsLibrary/>
          <div className={'separateBorder'}></div>
          <Button className={classesButtonRedirect.actionButton} onClick={() => handleOpenNewTab('https://www.facebook.com/')} variant="contained">{'Go to Facebook Feed'}</Button>
        </div>
        <ControlButtonsFeed/>
        <div className={'separateBorder'}></div>
        <a href='/ads.html' target='_blank' className={classes.link}><span>{'See your saved adds'}</span> <div><img src={arrow} alt=""/></div></a>
        <div className='developedBy'>
          <span>{''}</span>
        </div>
      </header>
    </div>
  );
}

export default App;
